117	snd_pcm_uframes_t snd_dmaengine_pcm_pointer(struct snd_pcm_substream *substream)
118	{
119		struct dmaengine_pcm_runtime_data *prtd = substream_to_prtd(substream);
120		uint32_t residue = 0;
121		enum dma_status status;
122		uint32_t pos = 0;
123		uint32_t buf_size;
124	
125		status = dmaengine_tx_status(prtd->dma_chan, &residue);
126		if (status == DMA_IN_PROGRESS || status == DMA_PAUSED) {
127			buf_size = snd_pcm_lib_buffer_bytes(substream);
128			if (residue > 0 && residue <= buf_size)
129				pos = buf_size - residue;
130		}
131		return bytes_to_frames(substream->runtime, pos);
132	}
