143	static void dmaengine_pcm_dma_complete(void *arg)
144	{
145		struct snd_pcm_substream *substream = arg;
146		struct dmaengine_pcm_runtime_data *prtd;
147	
148		if (!substream->runtime)
149			return;
150		prtd = substream_to_prtd(substream);
151		prtd->pos += snd_pcm_lib_period_bytes(substream);
152		if (prtd->pos >= snd_pcm_lib_buffer_bytes(substream))
153			prtd->pos = 0;
154		snd_pcm_period_elapsed(substream);
155	}
156	
157	static int dmaengine_pcm_prepare_and_submit(struct snd_pcm_substream *substream)
158	{
159		struct dmaengine_pcm_runtime_data *prtd = substream_to_prtd(substream);
160		struct dma_chan *chan = prtd->dma_chan;
161		enum dma_transfer_direction direction;
162		int ret = 0;
163		dma_callback callback;
164	
165		direction = snd_pcm_substream_to_dma_direction(substream);
166	
167		prtd->pos = 0;
168	
169		/* flush ringbuffer */
170		hal_dcache_clean_invalidate((unsigned long)(substream->runtime->dma_addr),
171					snd_pcm_lib_buffer_bytes(substream));
172	
173		ret = dmaengine_prep_dma_cyclic(chan,
174			substream->runtime->dma_addr,
175			snd_pcm_lib_buffer_bytes(substream),
176			snd_pcm_lib_period_bytes(substream), direction);
177		if (ret != 0) {
178			snd_err("[%s] dma cyclic failed!!!\n", __func__);
179			return ret;
180		}
181		callback = dmaengine_pcm_dma_complete;
182	
183		dmaengine_submit(chan, callback, (void *)substream);
184	
185		return 0;
186	}
