188	int snd_dmaengine_pcm_trigger(struct snd_pcm_substream *substream, int cmd)
189	{
190		struct dmaengine_pcm_runtime_data *prtd = substream_to_prtd(substream);
191		int ret;
192	
193		switch (cmd) {
194		case SNDRV_PCM_TRIGGER_START:
195			ret = dmaengine_pcm_prepare_and_submit(substream);
196			if (ret < 0)
197				return ret;
198			dma_async_issue_pending(prtd->dma_chan);
199			break;
200		case SNDRV_PCM_TRIGGER_RESUME:
201		case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
202			dmaengine_resume(prtd->dma_chan);
203			break;
204		case SNDRV_PCM_TRIGGER_SUSPEND:
205	#if 0
206			if (runtime->info & SNDRV_PCM_INFO_PAUSE)
207				dmaengine_pause(prtd->dma_chan);
208			else
209	#endif
210				dmaengine_terminate_async(prtd->dma_chan);
211			break;
212		case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
213			dmaengine_pause(prtd->dma_chan);
214			break;
215		case SNDRV_PCM_TRIGGER_STOP:
216			dmaengine_terminate_async(prtd->dma_chan);
217			break;
218		default:
219			return -EINVAL;
220		}
221	
222		return 0;
223	}

