438	static int snd_pcm_open_substream(struct snd_pcm *pcm, int stream)
439	{
440		int ret = 0;
441		struct snd_pcm_substream *substream;
442		struct snd_pcm_runtime *runtime;
443	
444		snd_print("\n");
445		substream = pcm->streams[stream];
446	
447		runtime = snd_malloc(sizeof(struct snd_pcm_runtime));
448		if (!runtime) {
449			snd_err("no memory\n");
450			ret = -ENOMEM;
451			goto error;
452		}
453	
454		runtime->tsleep = snd_schd_init();
455		if (runtime->tsleep == NULL) {
456			snd_err("semaphore tsleep create failed\n");
457			ret = -1;
458			goto error;
459		}
460	
461		runtime->sleep = snd_schd_init();
462		if (runtime->sleep == NULL) {
463			snd_err("semaphore sleep create failed\n");
464			ret = -1;
465			goto error;
466		}
467	
468		runtime->dsleep = snd_schd_init();
469		if (runtime->dsleep == NULL) {
470			snd_err("semaphore dsleep create failed\n");
471			ret = -1;
472			goto error;
473		}
474	
475		memset(runtime->dsleep_list, 0, sizeof(runtime->dsleep_list));
476	
477		runtime->status = snd_malloc(sizeof(struct snd_pcm_mmap_status));
478		if (!runtime->status) {
479			snd_err("no memory\n");
480			ret = -ENOMEM;
481			goto error;
482		}
483		runtime->control = snd_malloc(sizeof(struct snd_pcm_mmap_control));
484		if (!runtime->control) {
485			snd_err("no memory\n");
486			ret = -ENOMEM;
487			goto error;
488		}
489	
490		runtime->status->state = SNDRV_PCM_STATE_OPEN;
491		runtime->pcm_mutex = snd_mutex_init();
492	
493		/* substream is persistent across open/close (pcm->streams[stream]).
494		 * The codec dapm_control() early-returns when dapm_state already
495		 * matches, so a stale 1 left by a previous playback would skip the
496		 * DAC/analog re-enable on the next prepare → writei succeeds but the
497		 * codec stays silent. Force it back to 0 on every open. */
498		substream->dapm_state = 0;
499	
500		substream->runtime = runtime;
501		ret = snd_pcm_hw_constrains_init(substream);
502		if (ret < 0) {
503			snd_err("snd_pcm_hw_constrains_init failed\n");
504			goto error;
505		}
506	
507		ret = substream->ops->open(substream);
508		if (ret < 0)
509			goto error;
510	
511		substream->hw_opened = 1;
512	#ifndef CONFIG_SND_CORE_TINY
513		ret = snd_pcm_hw_constrains_complete(substream);
514		if (ret < 0) {
515			snd_err("snd_pcm_hw_constrains_complete failed\n");
516			goto error;
517		}
518	#endif
519	
520		return ret;
521	
522	error:
523		snd_pcm_release_substream(pcm, stream);
524		return ret;
525	}
