982	hal_dma_status_t hal_dma_start(struct sunxi_dma_chan *chan)
983	{
984	    uint32_t high = 0;
985	    uint32_t irq_val = 0;
986	    struct sunxi_dma_lli *prev = NULL;
987	    uint32_t desc_addr;
988	    unsigned long __cpsr, __ccpsr;
989	
990	    if (NULL == chan)
991	    {
992	        DMA_ERR("[dma] chan is NULL\n");
993	        return HAL_DMA_STATUS_INVALID_PARAMETER;
994	    }
995	
996	    if (chan->desc == NULL)
997	    {
998	        DMA_ERR("[dma] chan->desc is NULL\n");
999	        return HAL_DMA_STATUS_INVALID_PARAMETER;
1000	    }
1001	
1002	    __cpsr = hal_spin_lock_irqsave(&chan->lock);
1003	
1004	    if (chan->cyclic)
1005	        chan->irq_type = IRQ_PKG;
1006	    else
1007	        chan->irq_type = IRQ_QUEUE;
1008	
1009	    high = (chan->chan_count + START_CHAN_OFFSET >= HIGH_CHAN) ? 1 : 0;
1010	
1011	    __ccpsr = hal_spin_lock_irqsave(&dma_lock);
1012	    irq_val = hal_readl(DMA_IRQ_EN(high));
1013	    irq_val |= SHIFT_IRQ_MASK(chan->irq_type, chan->chan_count);
1014	    hal_writel(irq_val, DMA_IRQ_EN(high));
1015	    hal_spin_unlock_irqrestore(&dma_lock, __ccpsr);
1016	
1017	    /* FlashCtrl cannot support handshake mode  */
1018	    /* SET_OP_MODE(chan->chan_count, SRC_HS_MASK | DST_HS_MASK); */
1019	
1020	    for (prev = chan->desc; prev != NULL; prev = prev->vlln)
1021	    {
1022	        hal_dcache_clean((unsigned long)prev, sizeof(*prev));
1023	        /* k_dcache_clean(prev, sizeof(*prev)); */
1024	        //k_dcache_clean(prev->src, prev->len);
1025	        //k_dcache_clean_invalidate(prev->dst, prev->len);
1026	    }
1027	    desc_addr = __va_to_pa((unsigned long)chan->desc) - SUNXI_DMA_PHYADDR_OFFSET;
1028	    hal_writel(SET_DESC_HIGH_ADDR(desc_addr), DMA_LLI_ADDR(chan->chan_count));
1029	    hal_writel(CHAN_START, DMA_ENABLE(chan->chan_count));
1030	    sunxi_dump_com_regs();
1031	    sunxi_dump_chan_regs(chan);
1032	    hal_spin_unlock_irqrestore(&chan->lock, __cpsr);
1033	
1034	    return HAL_DMA_STATUS_OK;
1035	}
