1038	{
1039	    unsigned long __cpsr;
1040	
1041	    if (NULL == chan)
1042	    {
1043	        DMA_ERR("[dma] chan is NULL\n");
1044	        return HAL_DMA_STATUS_INVALID_PARAMETER;
1045	    }
1046	
1047	    __cpsr = hal_spin_lock_irqsave(&chan->lock);
1048	    /*We should entry PAUSE state first to avoid missing data
1049	    * count witch transferring on bus.
1050	    */
1051	    hal_writel(CHAN_PAUSE, DMA_PAUSE(chan->chan_count));
1052	    hal_writel(CHAN_STOP, DMA_ENABLE(chan->chan_count));
1053	    hal_writel(CHAN_RESUME, DMA_PAUSE(chan->chan_count));
1054	
1055	    if (chan->cyclic)
1056	    {
1057	        chan->cyclic = false;
1058	    }
