## 第三段：`sun8iw20-codec.c` → `sunxi_codec_trigger()` + `sunxi_codec_dapm_control()`（DAC FS 确认）

```c
static int sunxi_codec_trigger(struct snd_pcm_substream *substream,
        int cmd, struct snd_dai *dai)
{
    struct snd_codec *codec = dai->component;
    struct sunxi_codec_info *sunxi_codec = codec->private_data;
    const char *cmd_name;

    switch (cmd) {
    case SNDRV_PCM_TRIGGER_START:        cmd_name = "START"; break;
    case SNDRV_PCM_TRIGGER_RESUME:       cmd_name = "RESUME"; break;
    case SNDRV_PCM_TRIGGER_PAUSE_RELEASE: cmd_name = "PAUSE_RELEASE"; break;
    case SNDRV_PCM_TRIGGER_STOP:         cmd_name = "STOP"; break;
    case SNDRV_PCM_TRIGGER_SUSPEND:      cmd_name = "SUSPEND"; break;
    case SNDRV_PCM_TRIGGER_PAUSE_PUSH:   cmd_name = "PAUSE_PUSH"; break;
    default:                             cmd_name = "UNKNOWN"; break;
    }

    snd_print("\n");
    switch (cmd) {
    case SNDRV_PCM_TRIGGER_START:
    case SNDRV_PCM_TRIGGER_RESUME:
    case SNDRV_PCM_TRIGGER_PAUSE_RELEASE:
        if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
            snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
                (1 << DAC_DRQ_EN), (1 << DAC_DRQ_EN));      /* 开 DMA 请求 */
        }
        else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
            snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
                (1 << ADC_DRQ_EN), (1 << ADC_DRQ_EN));
            if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
                sunxi_rx_sync_control(..., 1);
        }
        break;
    case SNDRV_PCM_TRIGGER_STOP:
    case SNDRV_PCM_TRIGGER_SUSPEND:
    case SNDRV_PCM_TRIGGER_PAUSE_PUSH:
        if (substream->stream == SNDRV_PCM_STREAM_PLAYBACK) {
            snd_codec_update_bits(codec, SUNXI_DAC_FIFOC,
                (1 << DAC_DRQ_EN), (0 << DAC_DRQ_EN));      /* 关 DMA 请求 */
        }
        else if (substream->stream == SNDRV_PCM_STREAM_CAPTURE) {
            snd_codec_update_bits(codec, SUNXI_ADC_FIFOC,
                (1 << ADC_DRQ_EN), (0 << ADC_DRQ_EN));
            if (sunxi_codec->param.rx_sync_en && sunxi_codec->param.rx_sync_ctl)
                sunxi_rx_sync_control(..., 0);
        }
        break;
    default:
        return -EINVAL;
    }

    sunxi_codec_out_dump(codec, cmd_name);   /* 本轮新增：命令名打点 */
    return 0;
}
